SELECT "Rentabilidad_1"."Poblacion_Distribuidor_GVF_GVI" AS "Poblacion_Distribuidor_GVF_GVI",   ((CAST((CAST(SUM("Rentabilidad_1"."IN") AS double) / NULLIF(SUM("Rentabilidad_1"."CF"),0)) AS double) * CAST(cast('0.46999999999999997' as double) AS double)) - (CAST((SUM("Rentabilidad_1"."TOTAL_VENTA") + SUM("Rentabilidad_1"."TOTAL_REPARTO")) AS double) / NULLIF(SUM("Rentabilidad_1"."CF"),0))) AS "usr_Calculation_2160818191446896_ok" FROM "Rentabilidad_1" WHERE (("Rentabilidad_1"."Sede_Foraneo_Sintec" = 'Foraneo') AND ("Rentabilidad_1"."Zona" = 'NR')) GROUP BY "Rentabilidad_1"."Poblacion_Distribuidor_GVF_GVI";
